int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -EFAULT;

    if (!page) {
        page = alloc_pages(GFP_HIGHUSER | __GFP_ZERO, HPAGE_SHIFT);
        if (!page)
            return -ENOMEM;
        *pagep = page;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_SIZE))
        goto out;

    set_page_dirty(page);
    set_page_uptodate(page);

    spin_lock(&dst_mm->page_table_lock);
    set_pte_at(dst_mm, dst_addr, dst_pte, mk_pte(page, dst_vma->vm_page_prot));
    spin_unlock(&dst_mm->page_table_lock);

    ret = 0;

out:
    return ret;
}

int copy_huge_page_table_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                               struct vm_area_struct *dst_vma, unsigned long dst_addr,
                               unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -ENOMEM;

    if (!page) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
        *pagep = page;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_SIZE)) {
        put_page(page);
        return -EFAULT;
    }

    if (dst_vma->vm_flags & VM_SHARED) {
        set_page_dirty(page);
        set_page_shared(page);
    } else {
        set_page_private(page);
    }

    spin_lock(&dst_mm->page_table_lock);
    set_pte(dst_pte, mk_pte(page, dst_vma->vm_page_prot));
    spin_unlock(&dst_mm->page_table_lock);

    smp_wmb();

    return 0;
}

int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma,
                         unsigned long dst_addr, unsigned long src_addr,
                         struct page **pagep) {
    struct page *page = *pagep;
    int ret = 0;

    if (!page) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
    }

    if (!copy_user_highpage(page, src_addr)) {
        ret = -EFAULT;
        goto out;
    }

    SetPageUptodate(page);
    lock_page(page);

    {
        pte_t pte = pte_mkhuge(pte_mksrwx(0));
        pte = pte_set_flags(pte, PTE_DIRTY | PTE_ACCESSED);
        set_pte_at(dst_mm, dst_addr, dst_pte, pte);
    }

    /* Ensure that the PTE write is visible to other CPUs before unlocking */
    arch_flush_lazy_mmu();

    if (dst_vma->vm_flags & VM_SHARED) {
        /* Shared mapping: no further action */
    } else {
        /* Private mapping: take a reference for the new copy */
        get_page(page);
    }

    *pagep = page;
    unlock_page(page);

out:
    return ret;
}

int copy_huge_page_table_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                               struct vm_area_struct *dst_vma,
                               unsigned long dst_addr, unsigned long src_addr,
                               struct page **pagep) {
    struct page *page = *pagep;
    int ret = 0;

    if (!page) {
        page = alloc_huge_page();
        if (!page) {
            return -ENOMEM;
        }
        *pagep = page;
    }

    if (!copy_user_highpage(page, (void __user *)(unsigned long)src_addr)) {
        ret = -EFAULT;
        goto out;
    }

    set_page_private(page, dst_addr);
    set_page_state(page, HPAGE_PMD_NR);

    spin_lock(&dst_mm->page_table_lock);
    set_pte(dst_pte, pte_mkhuge(pte_mksrwx(pte_mkdirty(pte_mkwrite(pte_mksoft(pte_mkclean(PTE_NULL)))))));
    spin_unlock(&dst_mm->page_table_lock);

    smp_wmb();
    flush_tlb_page(dst_vma, dst_addr);

    return 0;

out:
    if (!*pagep) {
        __free_huge_page(page);
    }
    return ret;
}
